import Foundation
import DHCore

public enum InfrastructureKind:String,Codable,CaseIterable,Sendable { case substation,waterPump,refineryUnit,railLine,machineShop,radioRelay,bridge,mineVentilation }
public struct InfrastructureAsset:Identifiable,Codable,Sendable,Equatable { public let id:EntityID; public var name:String; public var kind:InfrastructureKind; public var condition:Double; public var online:Bool; public var settlementID:EntityID?; public init(id:EntityID=UUID(),name:String,kind:InfrastructureKind,condition:Double,online:Bool=false,settlementID:EntityID?=nil){self.id=id;self.name=name;self.kind=kind;self.condition=condition;self.online=online;self.settlementID=settlementID} }
public struct CivilizationRuntime:Codable,Sendable,Equatable { public var infrastructure:[EntityID:InfrastructureAsset]=[:]; public var populationTrend:[EntityID:Double]=[:]; public init(){}; public mutating func restore(_ id:EntityID,skill:Int,parts:Int)->Bool { guard var a=infrastructure[id],skill>=3,parts>=2 else{return false};a.condition=max(a.condition,0.75);a.online=true;infrastructure[id]=a;return true }; public mutating func applyEffects(to settlement:inout SettlementState){ let online=infrastructure.values.filter{$0.online && $0.settlementID==settlement.id}; for asset in online { switch asset.kind { case .substation: settlement.inventory[.electricity,default:0]+=25; case .waterPump: settlement.inventory[.water,default:0]+=30; case .machineShop: settlement.inventory[.parts,default:0]+=2; case .refineryUnit: settlement.inventory[.fuel,default:0]+=15; default: break } }; let essentials=min(settlement.inventory[.food,default:0],settlement.inventory[.water,default:0]); let delta = essentials>Double(settlement.population) ? 0.002:-0.003; populationTrend[settlement.id,default:0]+=delta; settlement.prosperity=max(0,min(1,settlement.prosperity+delta)) } }
